-- 425: WASSCE English summary multiple-choice set A and short-answer question (batch sprint 1).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_425_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_425_guard;
INSERT INTO _migration_425_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_001' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A good summary of a passage should' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. state the main points briefly in your own words","B. reproduce every sentence of the passage","C. add your own opinions to the writer''s ideas","D. copy the longest sentences word for word"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A summary condenses the passage to its main points in the candidate''s own words; copying sentences or adding opinions defeats the purpose.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_425_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_002' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following should normally be left out of a summary?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The main idea of each paragraph","B. Repetitions and illustrative examples","C. The writer''s overall conclusion","D. Important supporting arguments"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Summaries keep main ideas and conclusions but drop repetitions, examples and other illustrative detail that merely supports the main points.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_002' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_425_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_003' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The topic sentence of a paragraph usually' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. gives the writer''s biography","B. is always the longest sentence of the paragraph","C. states the main idea of the paragraph","D. asks the reader a direct question"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The topic sentence expresses the paragraph''s controlling idea, which the other sentences develop. It need not be the longest sentence or a question.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_003' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_425_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_004' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When a summary question says "in one sentence", the candidate must' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. write only one word as the answer","B. use exactly one line of the answer sheet","C. quote one sentence from the passage","D. combine the required points into a single grammatical sentence"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The instruction limits the form: the points must be joined into one grammatical sentence, often with conjunctions. Quoting the passage does not satisfy it.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_004' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_425_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_005' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Choose the best summary of the following. — "The factory closed in June. More than two hundred workers lost their jobs, and many shops in the town lost their customers."' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The factory''s closure cost many workers their jobs and the shops their customers.","B. The factory closed because two hundred workers lost their jobs in June.","C. Two hundred shops closed when the factory lost its customers.","D. The town''s shops closed in June, throwing factory workers out of work."]' AND q.correct_answer IS 'A' AND q.explanation IS 'A correct summary keeps both effects: job losses and lost customers. Each wrong option reverses the cause or confuses who closed and who lost customers.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_005' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_425_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_sa_001' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Combine the following into one summary sentence without losing the essential meaning: "The rains failed. The crops withered. The farmers travelled to the city in search of work."' AND q.question_type IS 'short_answer' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Because the rains failed and the crops withered, the farmers travelled to the city in search of work.' AND q.explanation IS 'The statements form a cause chain: failed rains withered the crops, so the farmers migrated to the city. Link all three with "because" and add nothing.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_sa_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s1_sum_mcq_001', 'topic_wassce_english_summary', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'A good summary of a passage should', 'multiple_choice', NULL, '["A. state the main points briefly in your own words","B. reproduce every sentence of the passage","C. add your own opinions to the writer''s ideas","D. copy the longest sentences word for word"]', 'A', 'A summary condenses the passage to its main points in the candidate''s own words; copying sentences or adding opinions defeats the purpose.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
