INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s1_sum_mcq_005', 'topic_wassce_english_summary', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Choose the best summary of the following. — "The factory closed in June. More than two hundred workers lost their jobs, and many shops in the town lost their customers."', 'multiple_choice', NULL, '["A. The factory''s closure cost many workers their jobs and the shops their customers.","B. The factory closed because two hundred workers lost their jobs in June.","C. Two hundred shops closed when the factory lost its customers.","D. The town''s shops closed in June, throwing factory workers out of work."]', 'A', 'A correct summary keeps both effects: job losses and lost customers. Each wrong option reverses the cause or confuses who closed and who lost customers.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Summarize', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s1_sum_sa_001', 'topic_wassce_english_summary', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Combine the following into one summary sentence without losing the essential meaning: "The rains failed. The crops withered. The farmers travelled to the city in search of work."', 'short_answer', NULL, NULL, 'Because the rains failed and the crops withered, the farmers travelled to the city in search of work.', 'The statements form a cause chain: failed rains withered the crops, so the farmers migrated to the city. Link all three with "because" and add nothing.', 'medium', '4', '2', '90', NULL, NULL, '1', NULL, NULL, 'Summarize', 'AO2', NULL, NULL, NULL);
